<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 11 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        int n = in.nextInt();
        double p = in.nextDouble();
        int x = 0;
        if (getProb(x, n) < p) {
            do {
                x++;
            } while (getProb(x, n) < p);
        }
        out.println(x);
        out.close();
    }

    static double getProb(int x, int n) {
        double term1 = 1.5 * x / n * (n - x) / (n - 1) * (n - x - 1) / (n - 2);
        double term2 = 3.0 * x / n * (x - 1) / (n - 1) * (n - x) / (n - 2);
        double term3 = 1.0 * x / n * (x - 1) / (n - 1) * (x - 2) / (n - 2);
        return term1 + term2 + term3;
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
    }

    static class OutputWriter {
        PrintWriter pw;

        OutputWriter(OutputStream os) {
            pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(os)));
        }

        void println(int i) {
            pw.println(i);
        }

        void close() {
            pw.close();
        }
    }
}
